package jp.yaegaki.equipment;
import android.content.*;import android.database.*;import android.database.sqlite.*;import android.security.keystore.*;import android.util.AtomicFile;
import org.json.*;import javax.crypto.*;import java.security.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public final class Store extends SQLiteOpenHelper {
 private final Context ctx;private final SecretKey key; final File photos;
 Store(Context c)throws Exception {super(c,"equipment.db",null,1);ctx=c;photos=new File(c.getFilesDir(),"photos");photos.mkdirs();KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias("equipment-v1")){KeyGenerator kg=KeyGenerator.getInstance("AES","AndroidKeyStore");kg.init(new KeyGenParameterSpec.Builder("equipment-v1",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());kg.generateKey();}key=(SecretKey)ks.getKey("equipment-v1",null);}
 Store(Context c,SecretKey testKey){super(c,"equipment.db",null,1);ctx=c;photos=new File(c.getFilesDir(),"photos");photos.mkdirs();key=testKey;}
 public void onCreate(SQLiteDatabase db){db.execSQL("CREATE TABLE devices(id TEXT PRIMARY KEY, data BLOB NOT NULL, updated INTEGER NOT NULL)");}
 public void onUpgrade(SQLiteDatabase db,int a,int b){throw new IllegalStateException("Unknown database version");}
 synchronized void save(JSONObject o)throws Exception{ContentValues v=new ContentValues();v.put("id",o.getString("id"));v.put("data",Crypto.encrypt(o.toString().getBytes(StandardCharsets.UTF_8),key));v.put("updated",System.currentTimeMillis());if(getWritableDatabase().insertWithOnConflict("devices",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new IOException("台帳の保存に失敗しました");}
 synchronized ArrayList<JSONObject> all()throws Exception{ArrayList<JSONObject> out=new ArrayList<>();try(Cursor c=getReadableDatabase().rawQuery("SELECT data FROM devices ORDER BY updated DESC",null)){while(c.moveToNext())out.add(new JSONObject(new String(Crypto.decrypt(c.getBlob(0),key),StandardCharsets.UTF_8)));}return out;}
 synchronized JSONObject get(String id)throws Exception{try(Cursor c=getReadableDatabase().rawQuery("SELECT data FROM devices WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(new String(Crypto.decrypt(c.getBlob(0),key),StandardCharsets.UTF_8)):null;}}
 synchronized void delete(String id){getWritableDatabase().delete("devices","id=?",new String[]{id});}
 private File photoFile(String id)throws Exception{if(!id.matches("[a-f0-9-]{36}\\.jpg"))throw new Exception("写真IDが不正です");return new File(photos,id);}
 String addPhoto(byte[] data)throws Exception{String id=UUID.randomUUID()+".jpg";writeAtomic(photoFile(id),Crypto.encrypt(data,key));return id;}
 byte[] photo(String id)throws Exception{return Crypto.decrypt(Files.readAllBytes(photoFile(id).toPath()),key);}
 void draft(JSONObject o)throws Exception{writeAtomic(new File(ctx.getFilesDir(),"draft"),Crypto.encrypt(o.toString().getBytes(StandardCharsets.UTF_8),key));}
 JSONObject draft()throws Exception{File f=new File(ctx.getFilesDir(),"draft");if(!f.exists())return null;return new JSONObject(new String(Crypto.decrypt(new AtomicFile(f).readFully(),key),StandardCharsets.UTF_8));}
 JSONObject aiSettings()throws Exception{File f=new File(ctx.getFilesDir(),"ai-settings");if(!f.exists())return new JSONObject();return new JSONObject(new String(Crypto.decrypt(new AtomicFile(f).readFully(),key),StandardCharsets.UTF_8));}
 void aiSettings(JSONObject o)throws Exception{writeAtomic(new File(ctx.getFilesDir(),"ai-settings"),Crypto.encrypt(o.toString().getBytes(StandardCharsets.UTF_8),key));}
 void clearDraft(){new AtomicFile(new File(ctx.getFilesDir(),"draft")).delete();}
 static void writeAtomic(File f,byte[] b)throws Exception{AtomicFile af=new AtomicFile(f);FileOutputStream out=null;try{out=af.startWrite();out.write(b);af.finishWrite(out);}catch(Exception e){af.failWrite(out);throw e;}}
 // Plaintext exists only in the encrypted backup stream, never in temporary disk files.
 void exportBackup(OutputStream target,char[] password)throws Exception{
  byte[] salt=new byte[16];new SecureRandom().nextBytes(salt);SecretKey bk=Crypto.passwordKey(password,salt);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,bk);
  target.write("EQBK01".getBytes(StandardCharsets.US_ASCII));target.write(salt);target.write(cipher.getIV());
  try(ZipOutputStream zip=new ZipOutputStream(new CipherOutputStream(target,cipher))){JSONArray arr=new JSONArray();HashSet<String> ids=new HashSet<>();for(JSONObject o:all()){arr.put(o);JSONArray a=o.optJSONArray("photos");if(a!=null)for(int i=0;i<a.length();i++)ids.add(a.getJSONObject(i).getString("file"));}zip.putNextEntry(new ZipEntry("manifest.json"));zip.write(new JSONObject().put("format",1).put("devices",arr).toString().getBytes(StandardCharsets.UTF_8));zip.closeEntry();for(String id:ids){zip.putNextEntry(new ZipEntry("photos/"+id));zip.write(photo(id));zip.closeEntry();}}
 }
 static byte[] limited(InputStream in,int max)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){if(out.size()+n>max)throw new Exception("ファイルが大きすぎます");out.write(buf,0,n);}return out.toByteArray();}
 // Verify authentication before changing the database. Import adds new IDs, never overwrites.
 int importBackup(InputStream in,char[] password)throws Exception{
  byte[] data=limited(in,160*1024*1024);if(data.length<50||!new String(data,0,6,StandardCharsets.US_ASCII).equals("EQBK01"))throw new Exception("バックアップ形式が違います");byte[] clear=Crypto.decrypt(Arrays.copyOfRange(data,22,data.length),Crypto.passwordKey(password,Arrays.copyOfRange(data,6,22)));
  HashMap<String,byte[]> entries=new HashMap<>();int total=0;try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(clear))){ZipEntry e;while((e=zip.getNextEntry())!=null){if(entries.size()>5000)throw new Exception("ファイル数が多すぎます");String name=e.getName();if(!name.equals("manifest.json")&&!name.matches("photos/[a-f0-9-]{36}\\.jpg"))throw new Exception("不正なバックアップです");byte[] b=limited(zip,16*1024*1024);total+=b.length;if(total>160*1024*1024)throw new Exception("バックアップが大きすぎます");if(entries.put(name,b)!=null)throw new Exception("重複ファイルがあります");}}
  byte[] manifest=entries.get("manifest.json");if(manifest==null)throw new Exception("台帳データがありません");JSONObject root=new JSONObject(new String(manifest,StandardCharsets.UTF_8));if(root.optInt("format")!=1)throw new Exception("未対応の形式です");JSONArray arr=root.getJSONArray("devices");ArrayList<File> created=new ArrayList<>();SQLiteDatabase db=getWritableDatabase();db.beginTransaction();boolean success=false;try{for(int i=0;i<arr.length();i++){JSONObject o=arr.getJSONObject(i);o.put("id",UUID.randomUUID().toString());JSONArray a=o.getJSONArray("photos");for(int p=0;p<a.length();p++){JSONObject ph=a.getJSONObject(p);byte[] b=entries.get("photos/"+ph.getString("file"));if(b==null)throw new Exception("写真が不足しています");String newId=addPhoto(b);created.add(photoFile(newId));ph.put("file",newId);}save(o);}db.setTransactionSuccessful();success=true;}finally{db.endTransaction();if(!success)for(File f:created)f.delete();Arrays.fill(clear,(byte)0);}return arr.length();
 }
 void cleanOrphans()throws Exception {HashSet<String> used=new HashSet<>();ArrayList<JSONObject> items=all();JSONObject d=draft();if(d!=null)items.add(d);for(JSONObject o:items){JSONArray a=o.optJSONArray("photos");if(a!=null)for(int i=0;i<a.length();i++)used.add(a.getJSONObject(i).optString("file"));}File[] files=photos.listFiles();if(files!=null)for(File f:files)if(!used.contains(f.getName()))f.delete();}
}
